    pricing_eyebrow:{ en:'Simple pricing', de:'Einfache Preise', es:'Precios sencillos', fr:'Tarifs simples', it:'Prezzi semplici', pt:'Preços simples', nl:'Eenvoudige prijzen', pl:'Proste ceny', ar:'أسعار بسيطة', zh:'简单定价', hi:'सरल मूल्य निर्धारण' },
    pricing_h2:   { en:'One payment. Use forever.', de:'Eine Zahlung. Für immer nutzen.', es:'Un pago. Para siempre.', fr:'Un paiement. Pour toujours.', it:'Un pagamento. Per sempre.', pt:'Um pagamento. Para sempre.', nl:'Eén betaling. Altijd gebruiken.', pl:'Jedna płatność. Na zawsze.', ar:'دفعة واحدة. للأبد.', zh:'一次付款，永久使用。', hi:'एक भुगतान। हमेशा के लिए।' },
    pricing_p:    { en:'No subscription. No hidden fees. No surprises.', de:'Kein Abonnement. Keine versteckten Gebühren. Keine Überraschungen.', es:'Sin suscripción. Sin tarifas ocultas. Sin sorpresas.', fr:'Pas d\'abonnement. Pas de frais cachés. Pas de surprises.', it:'Nessun abbonamento. Nessuna tariffa nascosta. Nessuna sorpresa.', pt:'Sem assinatura. Sem taxas ocultas. Sem surpresas.', nl:'Geen abonnement. Geen verborgen kosten. Geen verrassingen.', pl:'Bez subskrypcji. Bez ukrytych opłat. Bez niespodzianek.', ar:'بدون اشتراك. بدون رسوم خفية. بدون مفاجآت.', zh:'无订阅。无隐藏费用。无意外。', hi:'कोई सदस्यता नहीं। कोई छिपी हुई फीस नहीं। कोई आश्चर्य नहीं।' },
    pricing_badge:{ en:'All-in-one', de:'Alles inklusive', es:'Todo incluido', fr:'Tout inclus', it:'Tutto incluso', pt:'Tudo incluído', nl:'Alles inbegrepen', pl:'Wszystko w cenie', ar:'الكل في واحد', zh:'一体化', hi:'सब-इन-वन' },
    pricing_btn:  { en:'Start your journal', de:'Journal starten', es:'Iniciar el diario', fr:'Commencer mon journal', it:'Inizia il diario', pt:'Começar o diário', nl:'Start uw dagboek', pl:'Rozpocznij dziennik', ar:'ابدأ مذكراتك', zh:'开始记录', hi:'अपनी डायरी शुरू करें' },
    try_free:     { en:'Want to look before you buy? <a href="#sample">See sample journals on this page</a>, no signup needed.', de:'Erst schauen, dann kaufen? <a href="#sample">Beispiel-Journale auf dieser Seite ansehen</a>, keine Anmeldung erforderlich.', es:'¿Quiere ver antes de comprar? <a href="#sample">Vea diarios de muestra en esta página</a>, sin registro.', fr:'Vous voulez regarder avant d\'acheter ? <a href="#sample">Voir des journaux exemples sur cette page</a>, sans inscription.', it:'Vuoi guardare prima di acquistare? <a href="#sample">Vedi diari di esempio in questa pagina</a>, senza registrazione.', pt:'Quer ver antes de comprar? <a href="#sample">Veja diários de exemplo nesta página</a>, sem registo.', nl:'Wilt u kijken voor u koopt? <a href="#sample">Bekijk voorbeelddagboeken op deze pagina</a>, geen registratie nodig.', pl:'Chcesz zobaczyć przed zakupem? <a href="#sample">Zobacz przykładowe dzienniki na tej stronie</a>, bez rejestracji.', ar:'هل تريد النظر قبل الشراء؟ <a href="#sample">شاهد مذكرات نموذجية في هذه الصفحة</a>، لا حاجة للتسجيل.', zh:'想先看看再购买？<a href="#sample">在本页查看示例日记</a>，无需注册。', hi:'खरीदने से पहले देखना चाहते हैं? <a href="#sample">इस पेज पर नमूना डायरियां देखें</a>, साइनअप की जरूरत नहीं।' },

    /* ── Final CTA ── */
    final_h2:     { en:'A small thing today. An enormous gift later.', de:'Heute eine Kleinigkeit. Später ein riesiges Geschenk.', es:'Algo pequeño hoy. Un enorme regalo después.', fr:"Une petite chose aujourd'hui. Un immense cadeau plus tard.", it:'Una piccola cosa oggi. Un enorme regalo dopo.', pt:'Uma pequena coisa hoje. Um presente enorme depois.', nl:'Een kleine moeite nu. Een enorm geschenk later.', pl:'Mała rzecz dziś. Ogromny prezent później.', ar:'شيء صغير اليوم. هبة عظيمة لاحقاً.', zh:'今日一小步，日后一大礼。', hi:'आज एक छोटी बात। बाद में एक बड़ा उपहार।' },
    final_p:      { en:"An afternoon now will save your family weeks of searching, guessing and wondering at the worst time of their lives.", de:'Ein Nachmittag jetzt erspart Ihrer Familie wochenlange Suche und Raterei in der schlimmsten Zeit ihres Lebens.', es:'Una tarde ahora le ahorrará a su familia semanas de búsqueda y dudas en el peor momento de sus vidas.', fr:"Un après-midi maintenant épargnera à votre famille des semaines de recherche et d'incertitude au pire moment de leur vie.", it:"Un pomeriggio ora risparmierà alla tua famiglia settimane di ricerca e dubbi nel momento peggiore della loro vita.", pt:'Uma tarde agora vai poupar à sua família semanas de pesquisa e dúvidas no pior momento das suas vidas.', nl:'Een middag nu bespaart uw familie weken van zoeken en raden op het ergste moment van hun leven.', pl:'Popołudnie teraz oszczędzi Twojej rodzinie tygodnie poszukiwań i domysłów w najgorszym momencie ich życia.', ar:'بعض الوقت الآن سيوفر على عائلتك أسابيع من البحث والتخمين في أسوأ أوقات حياتهم.', zh:'现在花一个下午，能为您的家人省去在最艰难时刻数周的搜寻和猜测。', hi:'आज एक दोपहर का समय आपके परिवार को उनके जीवन के सबसे कठिन समय में हफ्तों की खोज और अनुमान से बचाएगा।' },
    final_btn:    { en:'Start your journal', de:'Journal starten', es:'Iniciar el diario', fr:'Commencer mon journal', it:'Inizia il diario', pt:'Começar o diário', nl:'Start uw dagboek', pl:'Rozpocznij dziennik', ar:'ابدأ مذكراتك', zh:'开始记录', hi:'अपनी डायरी शुरू करें' },
